import yaml
import tempfile

try:
    from urllib.request import urlopen
except ImportError:
    from urllib2 import urlopen


def save_dict_as_yaml(dictionary, prefix, dest_dir=None):
    if dest_dir is None:
        dest_dir = tempfile.gettempdir()
    dest_path = tempfile.mktemp(prefix=prefix, suffix='.env', dir=dest_dir)
    with open(dest_path, 'w') as _file:
        yaml.safe_dump(dictionary, _file, default_flow_style=False)

    return dest_path


def load_yaml(yaml_path):
    if not yaml_path.startswith("http://") and not yaml_path.startswith("https://"):
        with open(yaml_path, "r") as f:
            content = yaml.load(f, Loader=yaml.SafeLoader)
    else:
        response = urlopen(yaml_path)
        content = yaml.load(response.read(), Loader=yaml.SafeLoader)
        response.close()
    return content
